def svg(name, cls="", size=None):
    body = PATHS.get(name)
    if body is None:
        raise KeyError(f"unknown icon: {name}")
    fill = 'fill="currentColor" stroke="none"' if name in ("play", "pause") else 'fill="none" stroke="currentColor"'
    size_attr = f' width="{size}" height="{size}"' if size else ""
    c = f' class="{cls}"' if cls else ""
    return (f'<svg{c}{size_attr} viewBox="0 0 24 24" {fill} stroke-width="1.75" '
            f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>')
